import xml.etree.ElementTree as ET
from pathlib import Path

name_fragments = {
    'AKBA': ['AKEBIA'],
    'CAPR': ['CAPRICOR'],
    'CPRX': ['COEPTIS'],
    'DMRA': ['DERMIRA'],
    'IBRX': ['IMMUNITYBIO', 'NANTKWEST', 'IMMUNITY BIO'],
    'MDXG': ['MIMEDX'],
    'SLS': ['SELLAS'],
    'VSTM': ['VERASTEM'],
}

found = {}
cache = Path('/mnt/c/Projects/biotech_screener/biotech-screener/data/13f_cache')
for xml_file in sorted(cache.glob('*.xml'), reverse=True)[:500]:
    try:
        content = xml_file.read_text(errors='replace').upper()
        for ticker, frags in name_fragments.items():
            if ticker in found:
                continue
            if any(f in content for f in frags):
                # Parse to get CUSIP
                tree = ET.parse(xml_file)
                root = tree.getroot()
                for item in root.iter():
                    tag = item.tag.split('}')[-1] if '}' in item.tag else item.tag
                    if tag == 'infoTable':
                        children = {c.tag.split('}')[-1]: c.text for c in item}
                        name = (children.get('nameOfIssuer', '') or '').upper()
                        cusip = children.get('cusip', '').strip()
                        if any(f in name for f in frags) and cusip:
